 79	const (
 80		_ DatabaseProtocol = iota
 81		// DatabaseSQLite ...
 82		DatabaseSQLite
 83		// DatabasePostgres ...
 84		DatabasePostgres
 85		// DatabaseMySQL ...
 86		DatabaseMySQL
 87	)
