244	func Load(path string) (*Config, error) {
245		viper.SetEnvPrefix("FLIPT")
246		viper.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
247		viper.AutomaticEnv()
248	
249		viper.SetConfigFile(path)
250	
250	
251		if err := viper.ReadInConfig(); err != nil {
252			return nil, fmt.Errorf("loading configuration: %w", err)
253		}
254	
255		cfg := Default()
256	
257		// Logging
258		if viper.IsSet(logLevel) {
259			cfg.Log.Level = viper.GetString(logLevel)
260		}
261	
262		if viper.IsSet(logFile) {
263			cfg.Log.File = viper.GetString(logFile)
264		}
265	
266		// UI
267		if viper.IsSet(uiEnabled) {
268			cfg.UI.Enabled = viper.GetBool(uiEnabled)
269		}
270	
271		// CORS
272		if viper.IsSet(corsEnabled) {
273			cfg.Cors.Enabled = viper.GetBool(corsEnabled)
274	
275			if viper.IsSet(corsAllowedOrigins) {
276				cfg.Cors.AllowedOrigins = viper.GetStringSlice(corsAllowedOrigins)
277			}
278		}
279	
280		// Cache
281		if viper.IsSet(cacheMemoryEnabled) {
282			cfg.Cache.Memory.Enabled = viper.GetBool(cacheMemoryEnabled)
283	
284			if viper.IsSet(cacheMemoryExpiration) {
285				cfg.Cache.Memory.Expiration = viper.GetDuration(cacheMemoryExpiration)
286			}
287			if viper.IsSet(cacheMemoryEvictionInterval) {
288				cfg.Cache.Memory.EvictionInterval = viper.GetDuration(cacheMemoryEvictionInterval)
289			}
290		}
291	
292		// Server
293		if viper.IsSet(serverHost) {
294			cfg.Server.Host = viper.GetString(serverHost)
295		}
296	
297		if viper.IsSet(serverProtocol) {
298			cfg.Server.Protocol = stringToScheme[viper.GetString(serverProtocol)]
299		}
300	
301		if viper.IsSet(serverHTTPPort) {
302			cfg.Server.HTTPPort = viper.GetInt(serverHTTPPort)
303		}
304	
305		if viper.IsSet(serverHTTPSPort) {
306			cfg.Server.HTTPSPort = viper.GetInt(serverHTTPSPort)
307		}
308	
309		if viper.IsSet(serverGRPCPort) {
310			cfg.Server.GRPCPort = viper.GetInt(serverGRPCPort)
311		}
312	
313		if viper.IsSet(serverCertFile) {
314			cfg.Server.CertFile = viper.GetString(serverCertFile)
315		}
316	
317		if viper.IsSet(serverCertKey) {
318			cfg.Server.CertKey = viper.GetString(serverCertKey)
319		}
320	
321		// Tracing
322		if viper.IsSet(tracingJaegerEnabled) {
323			cfg.Tracing.Jaeger.Enabled = viper.GetBool(tracingJaegerEnabled)
324	
325			if viper.IsSet(tracingJaegerHost) {
326				cfg.Tracing.Jaeger.Host = viper.GetString(tracingJaegerHost)
327			}
328	
329			if viper.IsSet(tracingJaegerPort) {
330				cfg.Tracing.Jaeger.Port = viper.GetInt(tracingJaegerPort)
331			}
332		}
333	
334		// DB
335		if viper.IsSet(dbURL) {
336			cfg.Database.URL = viper.GetString(dbURL)
337	
338		} else if viper.IsSet(dbProtocol) || viper.IsSet(dbName) || viper.IsSet(dbUser) || viper.IsSet(dbPassword) || viper.IsSet(dbHost) || viper.IsSet(dbPort) {
339			cfg.Database.URL = ""
340	
341			if viper.IsSet(dbProtocol) {
342				cfg.Database.Protocol = stringToDatabaseProtocol[viper.GetString(dbProtocol)]
343			}
344	
345			if viper.IsSet(dbName) {
346				cfg.Database.Name = viper.GetString(dbName)
347			}
348	
349			if viper.IsSet(dbUser) {
350				cfg.Database.User = viper.GetString(dbUser)
351			}
352	
353			if viper.IsSet(dbPassword) {
354				cfg.Database.Password = viper.GetString(dbPassword)
355			}
356	
357			if viper.IsSet(dbHost) {
358				cfg.Database.Host = viper.GetString(dbHost)
359			}
360	
361			if viper.IsSet(dbPort) {
362				cfg.Database.Port = viper.GetInt(dbPort)
363			}
364	
365		}
366	
367		if viper.IsSet(dbMigrationsPath) {
368			cfg.Database.MigrationsPath = viper.GetString(dbMigrationsPath)
369		}
370	
371		if viper.IsSet(dbMaxIdleConn) {
372			cfg.Database.MaxIdleConn = viper.GetInt(dbMaxIdleConn)
373		}
374	
375		if viper.IsSet(dbMaxOpenConn) {
376			cfg.Database.MaxOpenConn = viper.GetInt(dbMaxOpenConn)
377		}
378	
379		if viper.IsSet(dbConnMaxLifetime) {
380			cfg.Database.ConnMaxLifetime = viper.GetDuration(dbConnMaxLifetime)
381		}
382	
383		// Meta
384		if viper.IsSet(metaCheckForUpdates) {
385			cfg.Meta.CheckForUpdates = viper.GetBool(metaCheckForUpdates)
386		}
387	
388		if err := cfg.validate(); err != nil {
389			return &Config{}, err
390		}
391	
392		return cfg, nil
393	}
394	
395	func (c *Config) validate() error {
396		if c.Server.Protocol == HTTPS {
397			if c.Server.CertFile == "" {
398				return errors.New("server.cert_file cannot be empty when using HTTPS")
399			}
400	
401			if c.Server.CertKey == "" {
402				return errors.New("server.cert_key cannot be empty when using HTTPS")
403			}
404	
405			if _, err := os.Stat(c.Server.CertFile); os.IsNotExist(err) {
406				return fmt.Errorf("cannot find TLS server.cert_file at %q", c.Server.CertFile)
407			}
408	
409			if _, err := os.Stat(c.Server.CertKey); os.IsNotExist(err) {
410				return fmt.Errorf("cannot find TLS server.cert_key at %q", c.Server.CertKey)
411			}
412		}
413	
414		if c.Database.URL == "" {
415			if c.Database.Protocol == 0 {
416				return fmt.Errorf("database.protocol cannot be empty")
417			}
418	
419			if c.Database.Host == "" {
420				return fmt.Errorf("database.host cannot be empty")
421			}
422	
423			if c.Database.Name == "" {
424				return fmt.Errorf("database.name cannot be empty")
425			}
426		}
427	
428		return nil
429	}
