431	func (c *Config) ServeHTTP(w http.ResponseWriter, r *http.Request) {
432		out, err := json.Marshal(c)
433		if err != nil {
434			w.WriteHeader(http.StatusInternalServerError)
435			return
436		}
437	
438		if _, err = w.Write(out); err != nil {
439			w.WriteHeader(http.StatusInternalServerError)
440			return
441		}
442	}
